              name="fullName"
              type="text"
              autocomplete="name"
              required
              aria-required="true"
              aria-describedby="full-name-error"
            />
            <p id="full-name-error" class="error-text" hidden></p>
          </div>

          <div class="form-field">
            <label for="email">Email address <span class="required-indicator" aria-hidden="true">*</span></label>
            <input
              id="email"
              name="email"
              type="email"
              autocomplete="email"
              inputmode="email"
              required
              aria-required="true"
              aria-describedby="email-error"
            />
            <p id="email-error" class="error-text" hidden></p>
          </div>

          <div class="form-field">
            <label for="phone">Phone number</label>
            <input
              id="phone"
              name="phone"
              type="tel"
              autocomplete="tel"
              inputmode="tel"
              aria-describedby="phone-help phone-error"
            />
