        {
          input: document.getElementById("full-name"),
          error: document.getElementById("full-name-error"),
          validate(value) {
            return value.trim() ? "" : "Enter your full name.";
          },
        },
        {
          input: document.getElementById("email"),
          error: document.getElementById("email-error"),
          validate(value) {
            if (!value.trim()) {
              return "Enter your email address.";
            }

            const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            return emailPattern.test(value.trim()) ? "" : "Enter a valid email address.";
          },
        },
        {
          input: document.getElementById("phone"),
          error: document.getElementById("phone-error"),
          validate(value) {
            if (!value.trim()) {
              return "";
            }

            const phonePattern = /^[+]?[\d\s().-]{7,20}$/;
            return phonePattern.test(value.trim())
              ? ""
              : "Use 7 to 20 digits and only spaces, parentheses, periods, or dashes.";
